'use client';

import * as React from 'react';

import { cn } from '@/lib/utils';
import { TooltipProvider } from '@/components/ui/tooltip';
import { CanvasSurface, CanvasZoomControls, useCanvasViewport } from '@/components/ui/workspace-kit/canvas';
import { useReducedMotion } from '@/components/ui/workspace-kit/reduced-motion';
import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { computeLayout, descendantsOf, effectiveParent, indexEdges, managersOf, nodeDataFor, type OrgLayout, type PlacedPerson } from '@/components/ui/org-chart/layout';
import { OrgChartDetails } from '@/components/ui/org-chart/org-chart-details';
import { OrgChartMoveDialog } from '@/components/ui/org-chart/org-chart-move-dialog';
import { OrgChartNode, type NodeHandlers } from '@/components/ui/org-chart/org-chart-node';
import { useScene, type DragState } from '@/components/ui/org-chart/org-chart-scene';
import { CHART_SPRING_STYLE } from '@/components/ui/org-chart/org-chart-spring';
import { OrgChartEmpty, OrgChartLoading } from '@/components/ui/org-chart/org-chart-states';
import type { OrgChartEdge, OrgChartNodeData } from '@/components/ui/org-chart/org-chart.types';
import { personName } from '@/components/ui/org-chart/org-chart-utils';
import { OrgChartWires } from '@/components/ui/org-chart/org-chart-wires';

/** Container width, at the default root font size, at or below which cards switch to their compact size. */
const COMPACT_MAX_WIDTH = 639;
/** Pointer travel, in screen pixels, before a press on a card becomes a drag. */
const DRAG_THRESHOLD = 4;
const CANVAS_INSET = { side: 24, top: 24, bottom: 64 };
const EMPTY_SET: ReadonlySet<string> = new Set();

/** The user's root font size over the 16px default: 1 normally, 2 at 200% text. */
function rootFontScale() {
	const size = parseFloat(getComputedStyle(document.documentElement).fontSize);
	return Number.isFinite(size) && size > 0 ? Math.round((size / 16) * 100) / 100 : 1;
}

/** Card text and avatars are sized in rem, so the card geometry follows the root font size instead of clipping it. */
function useRemScale() {
	const [scale, setScale] = React.useState(1);
	React.useEffect(() => {
		const update = () => setScale(rootFontScale());
		update();
		window.addEventListener('resize', update);
		const observer = new MutationObserver(update);
		observer.observe(document.documentElement, { attributes: true, attributeFilter: ['style', 'class'] });
		return () => {
			window.removeEventListener('resize', update);
			observer.disconnect();
		};
	}, []);
	return scale;
}

interface OrgChartPropsBase {
	/** Additional classes for the chart container (e.g. `"h-full"` to fill parent). Default height: 600px. */
	className?: string;
	/** Whether data is still loading */
	isLoading?: boolean;
	/** Whether the current user can manage the chart (drag, edit, remove) */
	editable?: boolean;
	/** Called when a node is dragged onto a new parent. In uncontrolled mode, the component updates visually first — if this throws, it reverts. */
	onReparent?: (childId: string, newParentId: string, preserve: { positionTitle?: string | null }) => void | Promise<void>;
	/** Called when the "Add first person" button is clicked (empty state) */
	onAddToChart?: () => void;
	/** Called when "Edit position" is selected from the node menu or details panel */
	onEditNode?: (nodeData: OrgChartNodeData) => void;
	/** Called when "Remove from chart" is selected from the node menu or details panel */
	onRemoveNode?: (nodeData: OrgChartNodeData) => void;
	/** Toast handler for reparent success/error messages. If not provided, no toasts are shown. */
	onReparentSuccess?: (childName: string, parentName: string) => void;
	onReparentError?: (message: string) => void;
	/** Show a panel for the selected person with their manager, reports, and actions. Default: true. */
	showDetails?: boolean;
	/** Called when the selected person changes; `null` when the selection clears. */
	onSelectNode?: (nodeData: OrgChartNodeData | null) => void;
	/** People whose reports start folded away, e.g. every manager below the second level in a large org. */
	defaultCollapsedIds?: readonly string[];
}

/** Controlled mode — consumer owns edge state */
interface OrgChartControlledProps extends OrgChartPropsBase {
	edges: OrgChartEdge[];
	defaultEdges?: never;
}

/** Uncontrolled mode — component manages edge state internally with optimistic reparent */
interface OrgChartUncontrolledProps extends OrgChartPropsBase {
	edges?: never;
	defaultEdges: OrgChartEdge[];
}

export type OrgChartProps = OrgChartControlledProps | OrgChartUncontrolledProps;

/** A press on a card, from pointer down until it ends; `stopListening` removes its window listeners. */
type Press = {
	id: string;
	pointerId: number;
	x: number;
	y: number;
	moved: boolean;
	blocked: ReadonlySet<string>;
	targetId: string | null;
	stopListening: () => void;
};

function edgesKey(edges: readonly OrgChartEdge[] | undefined) {
	return edges?.map((edge) => `${edge.id}:${edge.parentId}:${edge.positionTitle ?? ''}:${edge.displayName ?? ''}:${edge.avatarUrl ?? ''}`).join('|') ?? '';
}

function findNode(layer: HTMLElement | null, id: string) {
	if (!layer) return null;
	for (const node of layer.querySelectorAll<HTMLElement>('[data-node-id]')) if (node.dataset.nodeId === id) return node;
	return null;
}

/**
 * The neighbour at the same depth, left (-1) or right (+1), across subtrees. A stacked report's own column and
 * its siblings' columns are skipped: the stack handles those, so this only leaves the stack.
 */
function sideNeighbour(layout: OrgLayout, person: PlacedPerson, direction: -1 | 1) {
	const row = layout.people
		.filter((candidate) => candidate.depth === person.depth && !(person.stack && candidate !== person && candidate.stack && candidate.parentId === person.parentId))
		.sort((a, b) => a.x - b.x || a.y - b.y);
	return row[row.indexOf(person) + direction];
}

function OrgChartInner(props: OrgChartProps) {
	const {
		className,
		edges: controlledEdges,
		defaultEdges,
		isLoading = false,
		editable = true,
		showDetails = true,
		onAddToChart,
		onEditNode,
		onRemoveNode,
	} = props;
	const isControlled = controlledEdges !== undefined;
	const [internalEdges, setInternalEdges] = React.useState<readonly OrgChartEdge[]>(defaultEdges ?? []);
	// New defaultEdges content (not just a new array) resets the uncontrolled chart.
	const defaultKey = React.useMemo(() => edgesKey(defaultEdges), [defaultEdges]);
	const [syncedKey, setSyncedKey] = React.useState(defaultKey);
	if (!isControlled && defaultKey !== syncedKey) {
		setSyncedKey(defaultKey);
		setInternalEdges(defaultEdges ?? []);
	}
	const edges = controlledEdges ?? internalEdges;

	const containerRef = React.useRef<HTMLDivElement>(null);
	const layerRef = React.useRef<HTMLDivElement>(null);
	const [compact, setCompact] = React.useState(false);
	const [collapsed, setCollapsed] = React.useState<ReadonlySet<string>>(() => new Set(props.defaultCollapsedIds));
	const [selectedId, setSelectedId] = React.useState<string | null>(null);
	const [activeId, setActiveId] = React.useState<string | null>(null);
	const [moveId, setMoveId] = React.useState<string | null>(null);
	const [drag, setDrag] = React.useState<DragState | null>(null);
	const [revealRequest, setRevealRequest] = React.useState<{ id: string } | null>(null);
	/** The person the chart was last changed through (a fold, a drop); their card holds still as the layout reflows. */
	const [anchorId, setAnchorId] = React.useState<string | null>(null);
	const [announcement, setAnnouncement] = React.useState('');
	const press = React.useRef<Press | null>(null);
	const animate = !useReducedMotion();

	const scale = useRemScale();
	const index = React.useMemo(() => indexEdges(edges), [edges]);
	const layout = React.useMemo(() => computeLayout(index, compact, collapsed, scale), [index, compact, collapsed, scale]);
	const inset = React.useMemo(() => ({ side: CANVAS_INSET.side * scale, top: CANVAS_INSET.top * scale, bottom: CANVAS_INSET.bottom * scale }), [scale]);
	const selected = selectedId ? layout.byId.get(selectedId) : undefined;
	const tabStopId = activeId && layout.byId.has(activeId) ? activeId : (layout.people[0]?.data.id ?? null);

	const highlighted = React.useMemo<ReadonlySet<string>>(() => {
		if (!selected) return EMPTY_SET;
		const id = selected.data.id;
		return new Set([id, ...managersOf(index, id).slice(0, -1), ...selected.childIds]);
	}, [index, selected]);
	const scene = useScene(layout, anchorId, drag, highlighted, animate);
	const { shift } = scene;

	const viewport = useCanvasViewport(layout.width, {
		fit: 'contain',
		contentHeight: layout.height,
		contentOrigin: shift,
		minZoom: 0.3,
		maxZoom: 1.5,
		// Past this the names are unreadable; frame the top of the tree instead of all of it.
		minFitZoom: compact ? 0.7 : 0.5,
		inset,
	});

	React.useEffect(() => {
		const container = containerRef.current;
		if (!container || typeof ResizeObserver === 'undefined') return;
		const measure = () => setCompact(container.clientWidth <= COMPACT_MAX_WIDTH * scale);
		measure();
		const observer = new ResizeObserver(measure);
		observer.observe(container);
		return () => observer.disconnect();
	}, [scale]);

	// Ease a person into view once they are laid out (after unfolding their managers), framing
	// where their card will settle rather than where it is mid-spring.
	const { reveal, viewportRef, hold } = viewport;
	React.useEffect(() => {
		const person = revealRequest ? layout.byId.get(revealRequest.id) : undefined;
		if (person) reveal({ ...person, x: person.x + shift.x, y: person.y + shift.y });
	}, [layout, reveal, revealRequest, shift]);

	const latest = useLatest({ props, index, layout, shift, compact, view: viewport.view, isControlled });

	// A press still running when the chart unmounts must not leave window listeners behind.
	React.useEffect(() => () => press.current?.stopListening(), []);

	const select = React.useCallback(
		(id: string | null, andReveal = false) => {
			const { index, props, compact } = latest.current;
			setSelectedId(id);
			props.onSelectNode?.(id ? (nodeDataFor(index, id, compact) ?? null) : null);
			if (!id) return;
			// Unfold anyone above the person so they are on the chart.
			const above = new Set(managersOf(index, id));
			setCollapsed((current) => ([...above].some((manager) => current.has(manager)) ? new Set([...current].filter((manager) => !above.has(manager))) : current));
			setActiveId(id);
			if (andReveal) setRevealRequest({ id });
		},
		[latest],
	);

	// Folding a team keeps the person's card (and the pointer on its footer) where it is, and the view
	// stops auto-fitting: the chart reflows around the card instead of the camera jumping.
	const toggle = React.useCallback(
		(id: string) => {
			hold();
			setAnchorId(id);
			setCollapsed((current) => {
				const next = new Set(current);
				if (next.has(id)) next.delete(id);
				else next.add(id);
				return next;
			});
		},
		[hold],
	);

	const reparent = React.useCallback(
		async (childId: string, parentId: string) => {
			const { index, props, isControlled } = latest.current;
			const child = index.edges.get(childId);
			const parent = index.edges.get(parentId);
			if (!child || !parent || childId === parentId || effectiveParent(index, childId) === parentId) return;
			if (descendantsOf(index, childId).has(parentId)) {
				props.onReparentError?.('Cannot create circular reporting chain');
				setAnnouncement(`${personName(parent)} reports to ${personName(child)}, so they can't be their manager.`);
				return;
			}
			const preserve = { positionTitle: child.positionTitle };
			const previousParentId = child.parentId;
			// The new manager holds still while their team makes room.
			hold();
			setAnchorId(parentId);
			setCollapsed((current) => (current.has(parentId) ? new Set([...current].filter((id) => id !== parentId)) : current));
			if (!isControlled) setInternalEdges((current) => current.map((edge) => (edge.id === childId ? { ...edge, parentId } : edge)));
			try {
				await props.onReparent?.(childId, parentId, preserve);
				props.onReparentSuccess?.(child.displayName ?? 'Member', parent.displayName ?? 'new manager');
				setAnnouncement(`${personName(child)} now reports to ${personName(parent)}.`);
			} catch (error) {
				console.error('[OrgChart] reparent failed', error);
				if (!isControlled) {
					setInternalEdges((current) => current.map((edge) => (edge.id === childId && edge.parentId === parentId ? { ...edge, parentId: previousParentId } : edge)));
				}
				props.onReparentError?.('Failed to update reporting line');
				setAnnouncement(`${personName(child)}'s reporting line could not be changed.`);
			}
		},
		[hold, latest],
	);

	/** Brings a person's settled slot into view, even while their card is still springing there. */
	const revealPerson = React.useCallback(
		(id: string) => {
			const { layout, shift } = latest.current;
			const person = layout.byId.get(id);
			if (person) reveal({ ...person, x: person.x + shift.x, y: person.y + shift.y });
		},
		[latest, reveal],
	);

	const focusPerson = React.useCallback(
		(id: string | undefined) => {
			if (!id) return;
			const node = findNode(layerRef.current, id);
			if (!node) return;
			node.focus({ preventScroll: true });
			revealPerson(id);
		},
		[revealPerson],
	);

	/** Ends a press: a click selects, a drop on a manager reparents, and a dragged card springs back to its slot. */
	const endPress = React.useCallback(
		(drop: boolean) => {
			const current = press.current;
			if (!current) return;
			press.current = null;
			current.stopListening();
			if (!current.moved) {
				if (drop) select(current.id);
				return;
			}
			setDrag(null);
			if (drop && current.targetId) void reparent(current.id, current.targetId);
		},
		[reparent, select],
	);

	/** Past the drag threshold the pressed card follows the pointer, and the manager under it becomes the target. */
	const dragTo = React.useCallback(
		(event: PointerEvent) => {
			const current = press.current;
			if (!current) return;
			// No button held: the release happened somewhere we never heard about (a context menu, another
			// window). End the drag instead of letting the card follow the cursor.
			if ((event.buttons & 1) === 0) return endPress(false);
			const { props, layout, shift, view, index } = latest.current;
			if (props.editable === false) return;
			if (!current.moved) {
				if (Math.hypot(event.clientX - current.x, event.clientY - current.y) < DRAG_THRESHOLD) return;
				current.moved = true;
				current.blocked = new Set([current.id, ...descendantsOf(index, current.id)]);
			}
			const frame = viewportRef.current?.getBoundingClientRect();
			if (!frame) return;
			// Pointer in layout coordinates: canvas units, minus the shift that keeps the anchor still.
			const x = (event.clientX - frame.left - view.x) / view.zoom - shift.x;
			const y = (event.clientY - frame.top - view.y) / view.zoom - shift.y;
			const hit = layout.people.find(
				(person) => !current.blocked.has(person.data.id) && x >= person.x && x <= person.x + person.width && y >= person.y && y <= person.y + person.height,
			);
			current.targetId = hit && hit.data.id !== layout.byId.get(current.id)?.parentId ? hit.data.id : null;
			setDrag({
				id: current.id,
				dx: (event.clientX - current.x) / view.zoom,
				dy: (event.clientY - current.y) / view.zoom,
				targetId: current.targetId,
				blocked: current.blocked,
			});
		},
		[endPress, latest, viewportRef],
	);

	const canEdit = Boolean(onEditNode);
	const canRemove = Boolean(onRemoveNode);
	const edit = React.useMemo(
		() =>
			canEdit
				? (id: string) => {
						const data = latest.current.layout.byId.get(id)?.data;
						if (data) latest.current.props.onEditNode?.(data);
					}
				: undefined,
		[canEdit, latest],
	);
	const remove = React.useMemo(
		() =>
			canRemove
				? (id: string) => {
						const data = latest.current.layout.byId.get(id)?.data;
						if (data) latest.current.props.onRemoveNode?.(data);
					}
				: undefined,
		[canRemove, latest],
	);

	const handlers = React.useMemo<NodeHandlers>(
		() => ({
			pointerDown(id, event) {
				// One press at a time: a second finger or button never steals the card from the first.
				if (press.current || event.button !== 0 || (event.target as Element).closest('button, a, [role="menuitem"], [role="menu"]')) return;
				const { pointerId } = event;
				try {
					event.currentTarget.setPointerCapture(pointerId);
				} catch {
					// Capture is only a nicety here; the window listeners below see the whole press.
				}
				// Listen on the window, not the card: capture is lost if the card is re-inserted into
				// the DOM mid-drag (a host saving an earlier move), and the release must still end the press.
				const listeners = new AbortController();
				const options = { signal: listeners.signal };
				const own = (handler: (event: PointerEvent) => void) => (event: PointerEvent) => {
					if (event.pointerId === pointerId) handler(event);
				};
				window.addEventListener('pointermove', own(dragTo), options);
				window.addEventListener('pointerup', own(() => endPress(true)), options);
				window.addEventListener('pointercancel', own(() => endPress(false)), options);
				window.addEventListener('blur', () => endPress(false), options);
				window.addEventListener(
					'keydown',
					(keyEvent) => {
						if (keyEvent.key !== 'Escape') return;
						keyEvent.preventDefault();
						endPress(false);
					},
					options,
				);
				press.current = {
					id,
					pointerId,
					x: event.clientX,
					y: event.clientY,
					moved: false,
					blocked: EMPTY_SET,
					targetId: null,
					stopListening: () => listeners.abort(),
				};
			},
			keyDown(id, event) {
				if (event.target !== event.currentTarget) return;
				const { layout } = latest.current;
				const person = layout.byId.get(id);
				if (!person) return;
				const go = (next: string | undefined) => {
					event.preventDefault();
					focusPerson(next);
				};
				// A stacked report moves through its columns: up and down within one, left and right between them.
				const { stack } = person;
				switch (event.key) {
					case 'ArrowUp':
						return go((stack?.up ?? person.parentId) || undefined);
					case 'ArrowDown':
						if (person.collapsed) {
							event.preventDefault();
							return toggle(id);
						}
						return go(stack ? stack.down : person.childIds[0]);
					case 'ArrowLeft':
						return go(stack?.left ?? sideNeighbour(layout, person, -1)?.data.id);
					case 'ArrowRight':
						return go(stack?.right ?? sideNeighbour(layout, person, 1)?.data.id);
					case 'Home':
						return go(layout.people[0]?.data.id);
					case 'Enter':
					case ' ':
						event.preventDefault();
						return select(id);
					case 'Escape':
						// During a press, Escape cancels the drag (the window listener); otherwise it clears the selection.
						if (!press.current) select(null);
						return;
				}
			},
			focus(id, event) {
				if (event.target !== event.currentTarget) return;
				setActiveId(id);
				// Keyboard focus (Tab into the tree) brings the card into view; a press on it does not.
				if (!press.current) revealPerson(id);
			},
			toggle,
			openMove: setMoveId,
			edit,
			remove,
		}),
		[dragTo, edit, endPress, focusPerson, latest, remove, revealPerson, select, toggle],
	);

	const manager = selected?.parentId ? index.edges.get(selected.parentId) : undefined;
	const reports = selected
		? (index.children.get(selected.data.id) ?? []).flatMap((id): OrgChartEdge[] => {
				const report = index.edges.get(id);
				return report ? [report] : [];
			})
		: [];

	// Built once per change to the chart itself, so a pan (which re-renders this component every
	// frame) never walks hundreds of cards.
	const content = React.useMemo(
		() => (
			<>
				<OrgChartWires wires={scene.wires} anchors={scene.anchors} width={layout.width} height={layout.height} />
				<div role="tree" aria-label="Reporting lines">
					{scene.cards.map(({ person, x, y, enterFrom, leaving }) => {
						const id = person.data.id;
						const dragged = drag?.id === id ? drag : undefined;
						const target = dragged?.targetId ? layout.byId.get(dragged.targetId) : undefined;
						return (
							<OrgChartNode
								key={id}
								person={person}
								x={x}
								y={y}
								enterFrom={enterFrom}
								leaving={leaving}
								selected={id === selectedId}
								tabStop={id === tabStopId}
								editable={editable}
								drag={dragged ? { dx: dragged.dx, dy: dragged.dy, overTarget: Boolean(target) } : null}
								dropTarget={drag?.targetId === id}
								blocked={Boolean(drag?.blocked.has(id))}
								dropHint={target ? `Reports to ${personName(target.data)}` : undefined}
								handlers={handlers}
							/>
						);
					})}
				</div>
			</>
		),
		[drag, editable, handlers, layout, scene, selectedId, tabStopId],
	);

	// One container for every state, so the width observer keeps watching it when data arrives.
	return (
		<div ref={containerRef} style={CHART_SPRING_STYLE} className={cn('@container/chart relative h-[600px]', className)}>
			{isLoading ? (
				<OrgChartLoading />
			) : edges.length === 0 ? (
				<OrgChartEmpty editable={editable} onAddRoot={onAddToChart} />
			) : (
				<>
					<CanvasSurface
						viewport={viewport}
						layerRef={layerRef}
						className="absolute inset-0 h-auto"
						label="Organization chart. Drag or use arrow keys to pan, plus and minus to zoom. Tab into the chart to move between people with the arrow keys."
						onPaneClick={() => select(null)}
						overlay={
							<>
								{showDetails && selected ? (
									<OrgChartDetails
										key={selected.data.id}
										person={selected}
										manager={manager}
										reports={reports}
										editable={editable}
										onSelect={(id) => select(id, true)}
										onClose={() => {
											select(null);
											focusPerson(selected.data.id);
										}}
										onToggle={toggle}
										onMove={setMoveId}
										onEdit={handlers.edit}
										onRemove={handlers.remove}
									/>
								) : null}
								<CanvasZoomControls viewport={viewport} fit />
							</>
						}
					>
						{content}
					</CanvasSurface>
					<p role="status" aria-live="polite" className="sr-only">
						{announcement}
					</p>
					<OrgChartMoveDialog
						index={index}
						personId={moveId}
						onOpenChange={(open) => {
							if (!open) setMoveId(null);
						}}
						onMove={(personId, managerId) => {
							setMoveId(null);
							void reparent(personId, managerId);
						}}
					/>
				</>
			)}
		</div>
	);
}

export function OrgChart(props: OrgChartProps) {
	return (
		<TooltipProvider>
			<OrgChartInner {...props} />
		</TooltipProvider>
	);
}

'use client';

import { ChevronDown, Ellipsis, GitBranch, Pencil, Trash2, UserRound, UsersRound } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { CANVAS_NODE_ATTRIBUTE, NodeShell } from '@/components/ui/workspace-kit/canvas';
import { focusRingClass, pressClass } from '@/components/ui/workspace-kit/primitives';
import type { PlacedPerson } from '@/components/ui/org-chart/layout';
import { springTransition } from '@/components/ui/org-chart/org-chart-spring';
import { getInitials, personName, reportsLabel } from '@/components/ui/org-chart/org-chart-utils';

export type NodeHandlers = {
	/** Starts a press; the chart follows the pointer from there until it is released anywhere. */
	pointerDown: (id: string, event: React.PointerEvent<HTMLDivElement>) => void;
	keyDown: (id: string, event: React.KeyboardEvent<HTMLDivElement>) => void;
	focus: (id: string, event: React.FocusEvent<HTMLDivElement>) => void;
	toggle: (id: string) => void;
	openMove: (id: string) => void;
	edit?: (id: string) => void;
	remove?: (id: string) => void;
};

const MENU_ITEM = 'gap-2 [&_svg]:size-3.5 [&_svg]:text-muted-foreground';

export function PersonAvatar({ person, className }: { person: { displayName: string | null; avatarUrl: string | null }; className?: string }) {
	return (
		<Avatar className={cn('size-8 shrink-0 ring-1 ring-foreground/[0.06]', className)}>
			{person.avatarUrl ? <AvatarImage src={person.avatarUrl} alt="" /> : null}
			<AvatarFallback className="bg-muted text-[0.6875rem] font-medium text-muted-foreground">
				{getInitials(person.displayName) ?? <UserRound aria-hidden="true" className="size-[55%]" />}
			</AvatarFallback>
		</Avatar>
	);
}

/**
 * The card's actions menu. Until its first click it is a plain button that
 * looks the same, because a menu per card is a third of the cost of
 * unfolding a large team; the first click mounts the real menu, already open.
 */
function CardMenu({ id, name, selected, handlers }: { id: string; name: string; selected: boolean; handlers: NodeHandlers }) {
	const [mounted, setMounted] = React.useState(false);
	const trigger = {
		tabIndex: -1,
		'aria-label': `Actions for ${name}`,
		className: cn(
			'grid size-6 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground opacity-0 hover:bg-overlay-hover hover:text-foreground',
			'group-hover/node:opacity-100 group-focus-within/node:opacity-100 data-[popup-open]:opacity-100 pointer-coarse:opacity-100',
			selected && 'opacity-100',
			'transition-opacity duration-(--duration-fast) motion-reduce:transition-none',
			pressClass,
			focusRingClass,
		),
		children: <Ellipsis aria-hidden="true" className="size-3.5" />,
	};
	if (!mounted) return <button type="button" aria-haspopup="menu" {...trigger} onClick={() => setMounted(true)} />;
	return (
		<DropdownMenu defaultOpen>
			<DropdownMenuTrigger {...trigger} />
			<DropdownMenuContent align="start" side="right" className="w-48">
				<DropdownMenuItem className={MENU_ITEM} onClick={() => handlers.openMove(id)}>
					<GitBranch aria-hidden="true" />
					Change manager…
				</DropdownMenuItem>
				{handlers.edit ? (
					<DropdownMenuItem className={MENU_ITEM} onClick={() => handlers.edit?.(id)}>
						<Pencil aria-hidden="true" />
						Edit position
					</DropdownMenuItem>
				) : null}
				{handlers.remove ? (
					<>
						<DropdownMenuSeparator />
						<DropdownMenuItem
							className={cn(MENU_ITEM, 'text-destructive data-[highlighted]:bg-destructive/10 data-[highlighted]:text-destructive [&_svg]:text-destructive')}
							onClick={() => handlers.remove?.(id)}
						>
							<Trash2 aria-hidden="true" />
							Remove from chart
						</DropdownMenuItem>
					</>
				) : null}
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

type CardProps = {
	person: PlacedPerson;
	selected: boolean;
	editable: boolean;
	dragging: boolean;
	dropTarget: boolean;
	handlers: NodeHandlers;
};

/**
 * What a card draws: a double-framed card with the avatar, name, and title,
 * a menu for edits, and a footer that folds the person's reports away.
 * Memoised apart from the card's position, so a card that only moves never re-renders.
 */
const OrgCard = React.memo(function OrgCard({ person, selected, editable, dragging, dropTarget, handlers }: CardProps) {
	const { data, collapsed, hiddenCount } = person;
	const id = data.id;
	const name = personName(data);
	const compact = data.isCompact;
	const hasReports = data.childCount > 0;
	return (
		<>
			{collapsed ? (
				<>
					<span aria-hidden="true" className="absolute inset-x-2.5 -bottom-1.5 -z-10 h-4 rounded-b-[12px] border border-t-0 border-foreground/10 bg-muted" />
					<span aria-hidden="true" className="absolute inset-x-5 -bottom-3 -z-20 h-4 rounded-b-[10px] border border-t-0 border-foreground/[0.07] bg-muted/70" />
				</>
			) : null}
			<NodeShell
				tone={dropTarget ? 'target' : 'plain'}
				selected={selected}
				className={cn('h-full', dragging && 'shadow-card-lg')}
				cardClassName="min-h-0 flex-1"
				innerClassName="flex flex-col"
			>
				<div className={cn('flex min-h-0 flex-1 items-center', compact ? 'gap-2 pr-1.5 pl-2' : 'gap-2.5 pr-2 pl-2.5')}>
					<PersonAvatar person={data} className={compact ? 'size-6 text-[0.625rem]' : undefined} />
					<div className="min-w-0 flex-1">
						<p className={cn('truncate font-medium text-foreground', compact ? 'text-xs' : 'text-[0.8125rem]')} title={name}>
							{name}
						</p>
						{data.positionTitle ? (
							<p className={cn('truncate text-muted-foreground', compact ? 'text-[0.6875rem]' : 'text-xs')} title={data.positionTitle}>
								{data.positionTitle}
							</p>
						) : null}
					</div>
					{editable ? <CardMenu id={id} name={name} selected={selected} handlers={handlers} /> : null}
				</div>
				{hasReports ? (
					<button
						type="button"
						tabIndex={-1}
						aria-label={`${collapsed ? 'Show' : 'Hide'} ${reportsLabel(data.childCount)} of ${name}`}
						onClick={() => handlers.toggle(id)}
						className={cn(
							'flex shrink-0 cursor-pointer items-center gap-1.5 border-t border-dashed border-foreground/10 text-left text-muted-foreground hover:bg-overlay-hover hover:text-foreground',
							compact ? 'h-[1.625rem] px-2 text-[0.6875rem]' : 'h-7 px-2.5 text-xs',
							focusRingClass,
						)}
					>
						<UsersRound aria-hidden="true" className="size-3 shrink-0" />
						<span className="tabular-nums">{reportsLabel(data.childCount)}</span>
						{collapsed && hiddenCount > data.childCount ? (
							<span className="text-subtle-foreground tabular-nums">· {hiddenCount} in team</span>
						) : null}
						<ChevronDown
							aria-hidden="true"
							className={cn('ml-auto size-3 shrink-0 transition-transform duration-(--duration-moderate) ease-out motion-reduce:transition-none', collapsed && '-rotate-90')}
						/>
					</button>
				) : null}
			</NodeShell>
		</>
	);
}, sameBy<CardProps>({ person: sameCard }));

type OrgChartNodeProps = {
	person: PlacedPerson;
	/** Where the card is heading: its slot, or under a remaining manager while it is folded away. */
	x: number;
	y: number;
	/** Where a newly shown card starts: its manager's spot, so it slides out from under them. */
	enterFrom?: { x: number; y: number };
	/** Folded away or removed: sliding under a manager and about to unmount, no longer part of the tree. */
	leaving: boolean;
	selected: boolean;
	/** The one node in the tab order (roving tabindex). */
	tabStop: boolean;
	editable: boolean;
	/** Offset in canvas units while this card follows the pointer, and whether it is over a valid manager. */
	drag: { dx: number; dy: number; overTarget: boolean } | null;
	/** A valid manager under the dragged node. */
	dropTarget: boolean;
	/** Can't take the dragged node: it is the node itself or one of its reports. */
	blocked: boolean;
	/** Shown under the dragged card while it is over a valid manager, e.g. "Reports to Maya Chen". */
	dropHint?: string;
	handlers: NodeHandlers;
};

/**
 * One person on the canvas. Position changes spring through CSS transitions
 * on `left`/`top`; the whole card is the drag handle, while menu and footer
 * buttons keep their own presses.
 */
function OrgChartNodeView({ person, x, y, enterFrom, leaving, selected, tabStop, editable, drag, dropTarget, blocked, dropHint, handlers }: OrgChartNodeProps) {
	const { data, collapsed } = person;
	const id = data.id;
	const name = personName(data);
	const hasReports = data.childCount > 0;
	const dragging = drag !== null;
	const style: React.CSSProperties & Record<`--${string}`, string> = {
		left: x,
		top: y,
		width: person.width,
		height: person.height,
		// Managers sit above their reports, so teams slide out from under them and fold back beneath.
		zIndex: dragging ? 1000 : Math.max(1, 500 - person.depth),
		// Over a manager, the card shrinks a touch so the target's highlight shows through.
		transform: drag ? `translate(${drag.dx}px, ${drag.dy}px) scale(${drag.overTarget ? 0.9 : 1})` : undefined,
	};
	if (enterFrom) {
		style['--enter-left'] = `${enterFrom.x}px`;
		style['--enter-top'] = `${enterFrom.y}px`;
	}

	return (
		<div
			role="treeitem"
			aria-level={person.depth + 1}
			aria-posinset={person.position}
			aria-setsize={person.siblings}
			aria-selected={selected}
			aria-expanded={hasReports ? !collapsed : undefined}
			aria-label={[name, data.positionTitle, hasReports ? reportsLabel(data.childCount) : null].filter(Boolean).join(', ')}
			aria-hidden={leaving || undefined}
			tabIndex={tabStop && !leaving ? 0 : -1}
			data-node-id={leaving ? undefined : id}
			{...{ [CANVAS_NODE_ATTRIBUTE]: '' }}
			onPointerDown={leaving ? undefined : (event) => handlers.pointerDown(id, event)}
			onKeyDown={(event) => handlers.keyDown(id, event)}
			onFocus={(event) => handlers.focus(id, event)}
			style={style}
			className={cn(
				'group/node absolute isolate rounded-[14px]',
				focusRingClass,
				editable ? 'cursor-grab' : 'cursor-pointer',
				// Opacity stays out of the transition: fading many cards at once would give each its own layer.
				dragging ? cn('cursor-grabbing', drag.overTarget && 'opacity-85') : cn('transition-[left,top,transform]', springTransition),
				enterFrom && 'starting:left-(--enter-left) starting:top-(--enter-top)',
				blocked && !dragging && 'opacity-40',
				leaving && 'pointer-events-none',
			)}
		>
			{dropHint ? (
				<span
					aria-hidden="true"
					className="absolute top-full left-1/2 mt-2 -translate-x-1/2 animate-[ai-fade-up_var(--duration-moderate)_var(--ease-out)_both] rounded-md bg-foreground px-2 py-1 text-xs whitespace-nowrap text-background shadow-card-lg motion-reduce:animate-none"
				>
					{dropHint}
				</span>
			) : null}
			<OrgCard person={person} selected={selected} editable={editable} dragging={dragging} dropTarget={dropTarget} handlers={handlers} />
		</div>
	);
}

/** Everything a card draws. Its coordinates are left out: moving is the wrapper's job. */
function sameCard(a: PlacedPerson, b: PlacedPerson) {
	return (
		a.data.id === b.data.id &&
		a.data.displayName === b.data.displayName &&
		a.data.positionTitle === b.data.positionTitle &&
		a.data.avatarUrl === b.data.avatarUrl &&
		a.data.childCount === b.data.childCount &&
		a.data.isCompact === b.data.isCompact &&
		a.width === b.width &&
		a.height === b.height &&
		a.depth === b.depth &&
		a.collapsed === b.collapsed &&
		a.hiddenCount === b.hiddenCount &&
		a.position === b.position &&
		a.siblings === b.siblings
	);
}

/** Shallow props comparison, with a custom check for the listed props. */
function sameBy<P extends object>(checks: { [K in keyof P]?: (a: P[K], b: P[K]) => boolean }) {
	return (previous: P, next: P) => (Object.keys(next) as (keyof P)[]).every((key) => (checks[key] ?? Object.is)(previous[key], next[key]));
}

type Drag = OrgChartNodeProps['drag'];
const sameDrag = (a: Drag, b: Drag) => a === b || (a !== null && b !== null && a.dx === b.dx && a.dy === b.dy && a.overTarget === b.overTarget);

export const OrgChartNode = React.memo(
	OrgChartNodeView,
	// `enterFrom` only matters on the first render, when the card starts from it.
	sameBy<OrgChartNodeProps>({ person: sameCard, drag: sameDrag, enterFrom: (a, b) => Boolean(a) === Boolean(b) }),
);

'use client';

import { ChevronRight, ChevronsDownUp, ChevronsUpDown, GitBranch, Pencil, Trash2, X } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { NO_PAN_ATTRIBUTE } from '@/components/ui/workspace-kit/canvas';
import { enterClass, focusRingClass, TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import { dashedRule } from '@/components/ui/workspace-kit/surface';
import type { PlacedPerson } from '@/components/ui/org-chart/layout';
import { PersonAvatar } from '@/components/ui/org-chart/org-chart-node';
import type { OrgChartEdge } from '@/components/ui/org-chart/org-chart.types';
import { personName } from '@/components/ui/org-chart/org-chart-utils';

const ROW = cn(
	'flex h-8 w-full min-w-0 cursor-pointer items-center gap-2 rounded-md px-2 text-left text-[0.8125rem] text-foreground hover:bg-overlay-hover',
	focusRingClass,
);

function PersonRow({ person, onSelect }: { person: OrgChartEdge; onSelect: (id: string) => void }) {
	return (
		<li>
			<button type="button" className={ROW} onClick={() => onSelect(person.id)}>
				<PersonAvatar person={person} className="size-5 text-[0.5625rem]" />
				<span className="min-w-0 flex-1 truncate" title={personName(person)}>
					{personName(person)}
				</span>
				{person.positionTitle ? (
					<span className="hidden max-w-[45%] truncate text-xs text-muted-foreground @xs/details:block" title={person.positionTitle}>
						{person.positionTitle}
					</span>
				) : null}
				<ChevronRight aria-hidden="true" className="size-3.5 shrink-0 text-subtle-foreground" />
			</button>
		</li>
	);
}

function ActionRow({ icon: Icon, label, destructive, onClick }: { icon: LucideIcon; label: string; destructive?: boolean; onClick: () => void }) {
	return (
		<button
			type="button"
			onClick={onClick}
			className={cn(ROW, destructive ? 'text-destructive hover:bg-destructive/10' : null)}
		>
			<Icon aria-hidden="true" className={cn('size-3.5 shrink-0', destructive ? 'text-destructive' : 'text-muted-foreground')} />
			{label}
		</button>
	);
}

function Group({ label, count, children }: { label: string; count?: number; children: React.ReactNode }) {
	return (
		<section className={cn('flex flex-col gap-1 border-t px-2 pt-2.5 pb-2', dashedRule)}>
			<h3 className="flex items-center gap-1.5 px-2 text-xs text-muted-foreground">
				{label}
				{count === undefined ? null : <span className="tabular-nums text-subtle-foreground">{count}</span>}
			</h3>
			{children}
		</section>
	);
}

type OrgChartDetailsProps = {
	person: PlacedPerson;
	manager: OrgChartEdge | undefined;
	reports: readonly OrgChartEdge[];
	editable: boolean;
	onSelect: (id: string) => void;
	onClose: () => void;
	onToggle: (id: string) => void;
	onMove: (id: string) => void;
	onEdit?: (id: string) => void;
	onRemove?: (id: string) => void;
};

/**
 * Floating panel for the selected person: who they report to, their direct
 * reports (each one click away), and the actions the node menu offers, so
 * everything is reachable from the keyboard.
 */
export function OrgChartDetails({ person, manager, reports, editable, onSelect, onClose, onToggle, onMove, onEdit, onRemove }: OrgChartDetailsProps) {
	const { data } = person;
	const name = personName(data);
	const headingId = React.useId();

	return (
		<aside
			aria-labelledby={headingId}
			{...{ [NO_PAN_ATTRIBUTE]: '' }}
			onKeyDown={(event) => {
				if (event.key === 'Escape') {
					event.stopPropagation();
					onClose();
				}
			}}
			className={cn(
				'@container/details absolute z-20 flex cursor-auto flex-col overflow-y-auto rounded-xl bg-card shadow-card-lg select-text',
				'inset-x-3 bottom-14 max-h-[55%] @lg/chart:inset-x-auto @lg/chart:top-3 @lg/chart:right-3 @lg/chart:bottom-auto @lg/chart:max-h-[calc(100%-5.5rem)] @lg/chart:w-72',
				enterClass,
			)}
		>
			<header className="flex items-start gap-2.5 p-3">
				<PersonAvatar person={data} className="size-9 text-xs" />
				<div className="min-w-0 flex-1 pt-0.5">
					<h2 id={headingId} className="truncate text-sm font-medium text-foreground" title={name}>
						{name}
					</h2>
					{data.positionTitle ? (
						<p className="truncate text-xs text-muted-foreground" title={data.positionTitle}>
							{data.positionTitle}
						</p>
					) : null}
				</div>
				<TooltipIconButton label="Close details" size="sm" className="-mt-0.5 -mr-0.5" onClick={onClose}>
					<X aria-hidden="true" className="size-3.5" />
				</TooltipIconButton>
			</header>

			<Group label="Reports to">
				{manager ? (
					<ul>
						<PersonRow person={manager} onSelect={onSelect} />
					</ul>
				) : (
					<p className="px-2 py-1.5 text-[0.8125rem] text-muted-foreground">No one. {name} is at the top of the chart.</p>
				)}
			</Group>

			<Group label="Direct reports" count={reports.length}>
				{reports.length > 0 ? (
					<ul className="flex flex-col">
						{reports.map((report) => (
							<PersonRow key={report.id} person={report} onSelect={onSelect} />
						))}
					</ul>
				) : (
					<p className="px-2 py-1.5 text-[0.8125rem] text-muted-foreground">No direct reports.</p>
				)}
				{reports.length > 0 ? (
					<ActionRow
						icon={person.collapsed ? ChevronsUpDown : ChevronsDownUp}
						label={person.collapsed ? 'Show reports on the chart' : 'Fold reports away'}
						onClick={() => onToggle(data.id)}
					/>
				) : null}
			</Group>

			{editable ? (
				<Group label="Actions">
					<ActionRow icon={GitBranch} label="Change manager…" onClick={() => onMove(data.id)} />
					{onEdit ? <ActionRow icon={Pencil} label="Edit position" onClick={() => onEdit(data.id)} /> : null}
					{onRemove ? <ActionRow icon={Trash2} label="Remove from chart" destructive onClick={() => onRemove(data.id)} /> : null}
				</Group>
			) : null}
		</aside>
	);
}

'use client';

import * as React from 'react';

import { Command, CommandEmpty, CommandInput, CommandItem, CommandList } from '@/components/ui/command';
import { Dialog, DialogDescription, DialogHeader, DialogPopup, DialogTitle } from '@/components/ui/dialog';
import { ToneBadge } from '@/components/ui/workspace-kit/primitives';
import { descendantsOf, effectiveParent, type OrgIndex } from '@/components/ui/org-chart/layout';
import { PersonAvatar } from '@/components/ui/org-chart/org-chart-node';
import type { OrgChartEdge } from '@/components/ui/org-chart/org-chart.types';
import { personName } from '@/components/ui/org-chart/org-chart-utils';

type OrgChartMoveDialogProps = {
	index: OrgIndex;
	/** Person being moved; the dialog is open while this is set. */
	personId: string | null;
	onOpenChange: (open: boolean) => void;
	onMove: (personId: string, managerId: string) => void;
};

/**
 * Searchable list of everyone who can become this person's manager. Their
 * own reports are left out, since choosing one would make a loop.
 */
export function OrgChartMoveDialog({ index, personId, onOpenChange, onMove }: OrgChartMoveDialogProps) {
	const person = personId ? index.edges.get(personId) : undefined;
	// Keep the last person while the dialog animates closed.
	const [shown, setShown] = React.useState(person);
	if (person && person !== shown) setShown(person);
	const current = person ?? shown;

	const { managerId, candidates } = React.useMemo(() => {
		if (!current) return { managerId: null, candidates: [] as OrgChartEdge[] };
		const blocked = descendantsOf(index, current.id);
		const managerId = effectiveParent(index, current.id);
		const candidates = [...index.edges.values()]
			.filter((edge) => edge.id !== current.id && !blocked.has(edge.id))
			.sort((a, b) => (a.id === managerId ? -1 : b.id === managerId ? 1 : personName(a).localeCompare(personName(b))));
		return { managerId, candidates };
	}, [current, index]);

	const name = current ? personName(current) : '';
	const reportCount = current ? (index.children.get(current.id)?.length ?? 0) : 0;

	return (
		<Dialog open={Boolean(person)} onOpenChange={onOpenChange}>
			<DialogPopup className="max-w-md">
				<DialogHeader className="gap-1.5 pb-3">
					<DialogTitle className="text-base font-medium">Change manager for {name}</DialogTitle>
					<DialogDescription className="text-[0.8125rem]">
						{reportCount > 0
							? `${name}'s ${reportCount === 1 ? 'report moves' : `${reportCount} reports move`} with them.`
							: `Pick who ${name} reports to.`}
					</DialogDescription>
				</DialogHeader>
				<Command className="rounded-none border-t">
					<CommandInput placeholder="Search people" />
					<CommandList className="max-h-72 p-1">
						<CommandEmpty>No one matches.</CommandEmpty>
						{candidates.map((candidate) => {
							const isCurrent = candidate.id === managerId;
							return (
								<CommandItem
									key={candidate.id}
									value={`${personName(candidate)} ${candidate.positionTitle ?? ''} ${candidate.id}`}
									disabled={isCurrent}
									className="gap-2.5"
									onSelect={() => current && onMove(current.id, candidate.id)}
								>
									<PersonAvatar person={candidate} className="size-6 text-[0.625rem]" />
									<span className="min-w-0 flex-1">
										<span className="block truncate text-[0.8125rem]" title={personName(candidate)}>
											{personName(candidate)}
										</span>
										{candidate.positionTitle ? (
											<span className="block truncate text-xs text-muted-foreground" title={candidate.positionTitle}>
												{candidate.positionTitle}
											</span>
										) : null}
									</span>
									{isCurrent ? <ToneBadge tone="neutral">Current</ToneBadge> : null}
								</CommandItem>
							);
						})}
					</CommandList>
				</Command>
			</DialogPopup>
		</Dialog>
	);
}

import { Network, UserPlus } from 'lucide-react';
