'use client';

import * as React from 'react';

import { cn } from '@/lib/utils';
import { WIRE_STROKE, wirePath, type WirePoint, type WireTone } from '@/components/ui/workspace-kit/canvas';
import { STACK_CORNER } from '@/components/ui/org-chart/layout';
import { springTransition } from '@/components/ui/org-chart/org-chart-spring';

/**
 * A reporting line from the bottom centre of a manager's card to the top centre of a report's. A report in a
 * stack of columns has a routed line instead: square bends through `via`, ending at the left edge of its card.
 */
export type WireSpec = {
	id: string;
	start: WirePoint;
	end: WirePoint;
	via?: readonly WirePoint[];
	tone: WireTone;
	/** Marching dashes, for the drag preview. */
	marching: boolean;
	/** Follows a dragged card 1:1 instead of springing. */
	instant: boolean;
	/** Where a newly shown wire grows from: collapsed under its manager. */
	enter?: { start: WirePoint; end: WirePoint; via?: readonly WirePoint[] };
};

/** The dot under a manager where their reporting lines leave. */
export type AnchorSpec = { id: string; at: WirePoint; live: boolean; instant: boolean; enter?: WirePoint };

const samePoint = (a: WirePoint | undefined, b: WirePoint | undefined) => a === b || (a !== undefined && b !== undefined && a[0] === b[0] && a[1] === b[1]);
const samePoints = (a: readonly WirePoint[] | undefined, b: readonly WirePoint[] | undefined) =>
	a === b || (a !== undefined && b !== undefined && a.length === b.length && a.every((point, i) => samePoint(point, b[i])));

/** Points arrive as fresh arrays on every change, so compare them by value; `enter` only matters on the first render. */
function sameShape<T extends object>(a: T, b: T) {
	for (const key of Object.keys(b) as (keyof T)[]) {
		const [x, y] = [a[key], b[key]];
		if (key === 'enter' ? Boolean(x) !== Boolean(y) : key === 'via' ? !samePoints(x as WirePoint[] | undefined, y as WirePoint[] | undefined) : Array.isArray(x) ? !samePoint(x as WirePoint, y as WirePoint) : x !== y) return false;
	}
	return true;
}

const tenth = (value: number) => Math.round(value * 10) / 10;

/**
 * Square bends through the points, each softened by an arc of up to `STACK_CORNER`. A path with n points always has the
 * same commands, even when points coincide, so the browser can morph one into another (a line retracting into its manager).
 */
function routedPath(points: readonly WirePoint[]) {
	let d = `M ${tenth(points[0][0])} ${tenth(points[0][1])}`;
	for (let i = 1; i < points.length - 1; i += 1) {
		const [px, py] = points[i - 1];
		const [cx, cy] = points[i];
		const [nx, ny] = points[i + 1];
		const before = Math.hypot(cx - px, cy - py);
		const after = Math.hypot(nx - cx, ny - cy);
		const radius = Math.min(STACK_CORNER, before / 2, after / 2);
		const enter = before > 0 ? [cx - ((cx - px) / before) * radius, cy - ((cy - py) / before) * radius] : [cx, cy];
		const leave = after > 0 ? [cx + ((nx - cx) / after) * radius, cy + ((ny - cy) / after) * radius] : [cx, cy];
		d += ` L ${tenth(enter[0])} ${tenth(enter[1])} Q ${tenth(cx)} ${tenth(cy)}, ${tenth(leave[0])} ${tenth(leave[1])}`;
	}
	const last = points[points.length - 1];
	return `${d} L ${tenth(last[0])} ${tenth(last[1])}`;
}

const pathOf = (start: WirePoint, end: WirePoint, via?: readonly WirePoint[]) => (via ? routedPath([start, ...via, end]) : wirePath(start, end, 'vertical'));

const OrgWire = React.memo(function OrgWire({ start, end, via, tone, marching, instant, enter, marker }: Omit<WireSpec, 'id'> & { marker: string }) {
	const d = pathOf(start, end, via);
	const style = { d: `path("${d}")`, ...(enter ? { '--enter-d': `path("${pathOf(enter.start, enter.end, enter.via)}")` } : null) } as React.CSSProperties;
	return (
		<path
			d={d}
			style={style}
			fill="none"
			stroke={WIRE_STROKE[tone]}
			strokeWidth={1}
			strokeDasharray={tone === 'rest' ? undefined : '4 4'}
			strokeLinecap="round"
			markerEnd={`url(#${marker}-${tone === 'rest' ? 'rest' : 'live'})`}
			className={cn(instant ? 'transition-[stroke]' : cn('transition-[d,stroke]', springTransition), enter && 'starting:[d:var(--enter-d)]')}
		>
			{marching ? <animate attributeName="stroke-dashoffset" from="8" to="0" dur="0.5s" repeatCount="indefinite" /> : null}
		</path>
	);
}, sameShape);

const OrgAnchor = React.memo(function OrgAnchor({ at, live, instant, enter }: Omit<AnchorSpec, 'id'>) {
	const style = { cx: at[0], cy: at[1], ...(enter ? { '--enter-cx': `${enter[0]}px`, '--enter-cy': `${enter[1]}px` } : null) } as React.CSSProperties;
	return (
		<circle
			cx={at[0]}
			cy={at[1]}
			r={3}
			style={style}
			fill="var(--card)"
			stroke={WIRE_STROKE[live ? 'live' : 'rest']}
			strokeWidth={1}
			className={cn(
				instant ? 'transition-[stroke]' : cn('transition-[cx,cy,stroke]', springTransition),
				enter && 'starting:[cx:var(--enter-cx)] starting:[cy:var(--enter-cy)]',
			)}
		/>
	);
}, sameShape);

type OrgChartWiresProps = {
	wires: readonly WireSpec[];
	anchors: readonly AnchorSpec[];
	width: number;
	height: number;
};

/**
 * Every reporting line, then every anchor on top. Both lists keep a stable
 * order: moving an element in the DOM would cancel its running transition.
 */
export function OrgChartWires({ wires, anchors, width, height }: OrgChartWiresProps) {
	const marker = `org-wire-${React.useId().replace(/:/g, '')}`;
	return (
		<svg aria-hidden="true" className="pointer-events-none absolute top-0 left-0 overflow-visible" width={Math.max(1, width)} height={Math.max(1, height)}>
			<defs>
				{(['rest', 'live'] as const).map((tone) => (
					<marker key={tone} id={`${marker}-${tone}`} markerUnits="userSpaceOnUse" markerWidth={8} markerHeight={8} refX={4} refY={4} overflow="visible">
						<circle cx={4} cy={4} r={3} fill="var(--card)" stroke={WIRE_STROKE[tone]} strokeWidth={1} />
					</marker>
				))}
			</defs>
			{wires.map(({ id, ...wire }) => (
				<OrgWire key={id} {...wire} marker={marker} />
			))}
			{anchors.map(({ id, ...anchor }) => (
				<OrgAnchor key={id} {...anchor} />
			))}
		</svg>
	);
}

import type { WirePoint } from '@/components/ui/workspace-kit/canvas';
import type { OrgChartEdge, OrgChartNodeData } from '@/components/ui/org-chart/org-chart.types';

type Metrics = { width: number; header: number; footer: number; nodeGap: number; rankGap: number; treeGap: number; stackInset: number; stackGap: number };

const REGULAR: Metrics = { width: 232, header: 52, footer: 28, nodeGap: 24, rankGap: 72, treeGap: 56, stackInset: 20, stackGap: 12 };
const COMPACT: Metrics = { width: 184, header: 44, footer: 26, nodeGap: 12, rankGap: 56, treeGap: 32, stackInset: 16, stackGap: 8 };

/** More reports than this without a team of their own stack in columns under their manager instead of running in one row. */
const STACK_AFTER = 8;
/** Cards in a full stack column; a longer run gets more columns. */
const STACK_ROWS = 8;
/** Radius of the corners in a stacked report's line, which the lines of neighbouring reports overlap by so no corner leaves a gap. */
export const STACK_CORNER = 8;

/** Shell border (1) and bezel (3) on each side. */
const CHROME = 8;

/**
 * Card geometry in px at the default 16px root font size. `scale` is the user's root font size over 16, so
 * cards (whose avatar, name and footer are sized in rem) keep room for their content at larger text settings.
 */
export function metricsFor(compact: boolean, scale = 1): Metrics {
	const base = compact ? COMPACT : REGULAR;
	if (scale === 1) return base;
	const fit = (value: number) => Math.round(value * scale);
	return {
		width: fit(base.width),
		header: fit(base.header),
		footer: fit(base.footer),
		nodeGap: fit(base.nodeGap),
		rankGap: fit(base.rankGap),
		treeGap: fit(base.treeGap),
		stackInset: fit(base.stackInset),
		stackGap: fit(base.stackGap),
	};
}

/** Everyone indexed once: children sorted by name, roots in input order. */
export type OrgIndex = {
	edges: ReadonlyMap<string, OrgChartEdge>;
	children: ReadonlyMap<string, readonly string[]>;
	roots: readonly string[];
};

function byName(edges: ReadonlyMap<string, OrgChartEdge>) {
	return (a: string, b: string) => (edges.get(a)?.displayName ?? '').localeCompare(edges.get(b)?.displayName ?? '', undefined, { sensitivity: 'base' });
}

/**
 * Indexes flat edges into a forest. Anyone whose manager is missing (or is
 * themselves) becomes a root, and a cycle is broken at its first member, so
 * bad data still renders every person exactly once.
 */
export function indexEdges(list: readonly OrgChartEdge[]): OrgIndex {
	const edges = new Map(list.map((edge) => [edge.id, edge]));
	const children = new Map<string, string[]>();
	const roots: string[] = [];
	for (const edge of edges.values()) {
		const parent = edge.parentId && edge.parentId !== edge.id && edges.has(edge.parentId) ? edge.parentId : null;
		if (!parent) {
			roots.push(edge.id);
			continue;
		}
		const siblings = children.get(parent);
		if (siblings) siblings.push(edge.id);
		else children.set(parent, [edge.id]);
	}
	const compare = byName(edges);
	for (const siblings of children.values()) siblings.sort(compare);

	const reached = new Set<string>();
	const walk = (id: string) => {
		if (reached.has(id)) return;
		reached.add(id);
		for (const child of children.get(id) ?? []) walk(child);
	};
	roots.forEach(walk);
	for (const id of edges.keys()) {
		if (reached.has(id)) continue;
		roots.push(id);
		walk(id);
	}
	return { edges, children, roots };
}

/** Everyone below `id`, however deep. */
export function descendantsOf(index: OrgIndex, id: string): Set<string> {
	const found = new Set<string>();
	const stack = [...(index.children.get(id) ?? [])];
	while (stack.length > 0) {
		const next = stack.pop()!;
		if (found.has(next) || next === id) continue;
		found.add(next);
		stack.push(...(index.children.get(next) ?? []));
	}
	return found;
}

/** The chain of managers above `id`, nearest first. */
export function managersOf(index: OrgIndex, id: string): string[] {
	const chain: string[] = [];
	const seen = new Set([id]);
	let parent = effectiveParent(index, id);
	while (parent && !seen.has(parent)) {
		chain.push(parent);
		seen.add(parent);
		parent = effectiveParent(index, parent);
	}
	return chain;
}

export function effectiveParent(index: OrgIndex, id: string): string | null {
	const parentId = index.edges.get(id)?.parentId;
	return parentId && index.children.get(parentId)?.includes(id) ? parentId : null;
}

/** A person's node data straight from the index, whether or not they are on screen. */
export function nodeDataFor(index: OrgIndex, id: string, compact: boolean): OrgChartNodeData | undefined {
	const edge = index.edges.get(id);
	if (!edge) return undefined;
	return { ...edge, childCount: index.children.get(id)?.length ?? 0, isRoot: effectiveParent(index, id) === null, isCompact: compact };
}

/** Where a stacked report sits in its manager's columns, for the arrow keys, and the line that reaches it. */
export type StackSlot = {
	/** The report above and below in the same column, and in the same row of the columns either side. */
	up?: string;
	down?: string;
	left?: string;
	right?: string;
	/** From the manager's card, along a bus and down this column's spine, into the left edge of the card. */
	route: readonly WirePoint[];
};

export type PlacedPerson = {
	data: OrgChartNodeData;
	x: number;
	y: number;
	width: number;
	height: number;
	/** 0 for roots. */
	depth: number;
	/** Visible parent; null for roots. */
	parentId: string | null;
	/** Visible direct reports, left to right; reports without a team who fill columns come last, column by column. */
	childIds: readonly string[];
	/** Set for a report in a stack of columns under the manager. */
	stack?: StackSlot;
	collapsed: boolean;
	/** Everyone hidden under a collapsed node. */
	hiddenCount: number;
	/** 1-based position among siblings, and the sibling count, for the tree's ARIA attributes. */
	position: number;
	siblings: number;
};

export type OrgLayout = {
	people: readonly PlacedPerson[];
	byId: ReadonlyMap<string, PlacedPerson>;
	width: number;
	height: number;
	nodeWidth: number;
};

/**
 * Tidy top-down tree: each subtree is as wide as its children (or one card),
 * parents centre over their children, and each rank sits one step lower.
 * Reports without a team of their own stack in columns once there are too
 * many for a row (see `STACK_AFTER`). Collapsed nodes keep their card but hide
 * everyone below. Coordinates start at 0, so the content box is `width` by `height`.
 */
export function computeLayout(index: OrgIndex, compact: boolean, collapsed: ReadonlySet<string>, scale = 1): OrgLayout {
	const metrics = metricsFor(compact, scale);
	const step = CHROME + metrics.header + metrics.footer + metrics.rankGap;
	const leafHeight = CHROME + metrics.header;
	const visibleChildren = (id: string) => (collapsed.has(id) ? [] : (index.children.get(id) ?? []));

	/**
	 * The reports without a team of their own, when there are too many for one row: they fill columns under their
	 * manager (a row of 40 is 10,000px wide) while reports with a team stay in the row.
	 */
	const stackPlan = (kids: readonly string[]) => {
		const leaves = kids.filter((kid) => !index.children.get(kid)?.length);
		if (leaves.length <= STACK_AFTER) return null;
		const rows = Math.ceil(leaves.length / Math.ceil(leaves.length / STACK_ROWS));
		const columns = Math.ceil(leaves.length / rows);
		return { leaves, members: new Set(leaves), rows, columns, width: columns * (metrics.stackInset + metrics.width) + (columns - 1) * metrics.nodeGap };
	};
	type StackPlan = NonNullable<ReturnType<typeof stackPlan>>;

	const widths = new Map<string, number>();
	const subtreeWidth = (id: string, trail: Set<string>): number => {
		const cached = widths.get(id);
		if (cached !== undefined) return cached;
		trail.add(id);
		const kids = visibleChildren(id).filter((child) => !trail.has(child));
		const plan = stackPlan(kids);
		const blocks = (plan ? kids.filter((kid) => !plan.members.has(kid)) : kids).map((child) => subtreeWidth(child, trail));
		if (plan) blocks.push(plan.width);
		const span = blocks.reduce((sum, block) => sum + block, 0) + Math.max(0, blocks.length - 1) * metrics.nodeGap;
		trail.delete(id);
		const width = Math.max(metrics.width, span);
		widths.set(id, width);
		return width;
	};

	const people: PlacedPerson[] = [];
	const byId = new Map<string, PlacedPerson>();
	let height = 0;

	const place = (id: string, left: number, depth: number, parentId: string | null, position: number, siblings: number, stacked?: { x: number; y: number; slot: StackSlot }) => {
		const edge = index.edges.get(id);
		if (!edge || byId.has(id)) return;
		const allChildren = index.children.get(id) ?? [];
		const isCollapsed = collapsed.has(id) && allChildren.length > 0;
		const kids = isCollapsed ? [] : allChildren.filter((child) => !byId.has(child) && child !== id);
		const plan = stackPlan(kids);
		const lead = plan ? kids.filter((kid) => !plan.members.has(kid)) : kids;
		const width = subtreeWidth(id, new Set());
		const nodeHeight = CHROME + metrics.header + (allChildren.length > 0 ? metrics.footer : 0);
		const person: PlacedPerson = {
			data: {
				...edge,
				childCount: allChildren.length,
				isRoot: parentId === null,
				isCompact: compact,
			},
			x: stacked ? stacked.x : left + (width - metrics.width) / 2,
			y: stacked ? stacked.y : depth * step,
			width: metrics.width,
			height: nodeHeight,
			depth,
			parentId,
			childIds: plan ? [...lead, ...plan.leaves] : kids,
			stack: stacked?.slot,
			collapsed: isCollapsed,
			hiddenCount: isCollapsed ? descendantsOf(index, id).size : 0,
			position,
			siblings,
		};
		people.push(person);
		byId.set(id, person);
		height = Math.max(height, person.y + nodeHeight);

		const blocks = lead.map((child) => widths.get(child) ?? metrics.width);
		if (plan) blocks.push(plan.width);
		const span = blocks.reduce((sum, block) => sum + block, 0) + Math.max(0, blocks.length - 1) * metrics.nodeGap;
		const reports = lead.length + (plan ? plan.leaves.length : 0);
		let cursor = left + (width - span) / 2;
		lead.forEach((child, childIndex) => {
			place(child, cursor, depth + 1, id, childIndex + 1, reports);
			cursor += (widths.get(child) ?? metrics.width) + metrics.nodeGap;
		});
		if (plan) placeStack(plan, person, cursor, lead.length, reports);
	};

	/**
	 * Lays a manager's stacked reports out column by column, top to bottom, left to right. Each report's line is
	 * its own piece of the whole (trunk, bus, column spine, stub), so pieces never overlap and darken where they would.
	 */
	const placeStack = (plan: StackPlan, manager: PlacedPerson, left: number, before: number, siblings: number) => {
		const pitch = leafHeight + metrics.stackGap;
		const columnPitch = metrics.stackInset + metrics.width + metrics.nodeGap;
		const top = (manager.depth + 1) * step;
		const trunk: WirePoint = [manager.x + metrics.width / 2, manager.y + manager.height];
		const bus = trunk[1] + metrics.rankGap / 2;
		const total = plan.leaves.length;
		const columnLength = (column: number) => Math.min(plan.rows, total - column * plan.rows);
		plan.leaves.forEach((id, position) => {
			const column = Math.floor(position / plan.rows);
			const row = position % plan.rows;
			const x = left + column * columnPitch + metrics.stackInset;
			const y = top + row * pitch;
			const mid = y + leafHeight / 2;
			const spine = x - metrics.stackInset / 2;
			const route: WirePoint[] =
				row > 0
					? [[spine, mid - pitch - STACK_CORNER], [spine, mid], [x, mid]]
					: column > 0
						? [[spine - columnPitch - STACK_CORNER, bus], [spine, bus], [spine, mid], [x, mid]]
						: [trunk, [trunk[0], bus], [spine, bus], [spine, mid], [x, mid]];
			const slot: StackSlot = {
				up: row > 0 ? plan.leaves[position - 1] : undefined,
				down: row < columnLength(column) - 1 ? plan.leaves[position + 1] : undefined,
				left: column > 0 ? plan.leaves[(column - 1) * plan.rows + Math.min(row, columnLength(column - 1) - 1)] : undefined,
				right: column < plan.columns - 1 ? plan.leaves[(column + 1) * plan.rows + Math.min(row, columnLength(column + 1) - 1)] : undefined,
				route,
			};
			place(id, x, manager.depth + 1, manager.data.id, before + position + 1, siblings, { x, y, slot });
		});
	};

	let cursor = 0;
	index.roots.forEach((root, rootIndex) => {
		if (byId.has(root)) return;
		place(root, cursor, 0, null, rootIndex + 1, index.roots.length);
		cursor += subtreeWidth(root, new Set()) + metrics.treeGap;
	});

	return { people, byId, width: Math.max(0, cursor - metrics.treeGap), height, nodeWidth: metrics.width };
}

'use client';

import * as React from 'react';

import type { WirePoint } from '@/components/ui/workspace-kit/canvas';
import type { OrgLayout, PlacedPerson } from '@/components/ui/org-chart/layout';
import { CHART_SPRING } from '@/components/ui/org-chart/org-chart-spring';
import type { AnchorSpec, WireSpec } from '@/components/ui/org-chart/org-chart-wires';

/** A card being dragged: its offset in canvas units and the manager it would report to if dropped now. */
export type DragState = { id: string; dx: number; dy: number; targetId: string | null; blocked: ReadonlySet<string> };

/** A card on the canvas: where it is heading, where a new one grows from, and whether it is folding away. */
export type SceneCard = { person: PlacedPerson; x: number; y: number; enterFrom?: { x: number; y: number }; leaving: boolean };

type Point = { x: number; y: number };
type Spot = Point & { width: number; height: number };
type Leaving = { person: PlacedPerson; anchorId: string };
/**
 * `shift` moves the whole layout on the canvas so the anchor person stays
 * put across layout changes; `beforeShift` is the shift `before` was drawn with.
 */
type Scene = { layout: OrgLayout; before: OrgLayout | null; leaving: ReadonlyMap<string, Leaving>; shift: Point; beforeShift: Point };

const EMPTY: ReadonlyMap<string, Leaving> = new Map();
const ORIGIN: Point = { x: 0, y: 0 };
const top = (spot: Spot): WirePoint => [spot.x + spot.width / 2, spot.y];
const bottom = (spot: Spot): WirePoint => [spot.x + spot.width / 2, spot.y + spot.height];

/** The closest manager above `id` (in `before`) who is still on the chart `after`. */
function nearestShown(before: OrgLayout, after: OrgLayout, id: string) {
	let current = before.byId.get(id)?.parentId ?? null;
	while (current && !after.byId.has(current)) current = before.byId.get(current)?.parentId ?? null;
	return current ? after.byId.get(current) : undefined;
}

/**
 * People who just left the chart keep sliding under the nearest manager still
 * on it; everyone else is laid out afresh, shifted so the anchor stays put.
 */
function nextScene(scene: Scene, layout: OrgLayout, anchorId: string | null, animate: boolean): Scene {
	const was = anchorId ? scene.layout.byId.get(anchorId) : undefined;
	const now = anchorId ? layout.byId.get(anchorId) : undefined;
	const shift = was && now ? { x: scene.shift.x + was.x - now.x, y: scene.shift.y + was.y - now.y } : scene.shift;
	const base = { layout, before: scene.layout, shift, beforeShift: scene.shift };
	if (!animate) return { ...base, leaving: EMPTY };
	const leaving = new Map<string, Leaving>();
	for (const [id, item] of scene.leaving) if (!layout.byId.has(id) && layout.byId.has(item.anchorId)) leaving.set(id, item);
	for (const person of scene.layout.people) {
		const id = person.data.id;
		if (layout.byId.has(id)) continue;
		const anchor = nearestShown(scene.layout, layout, id);
		if (anchor) leaving.set(id, { person, anchorId: anchor.data.id });
	}
	return { ...base, leaving };
}

/**
 * Turns each new layout into what the canvas draws, so every change springs:
 * new reports slide out from under their manager, folded-away reports slide
 * back beneath the nearest manager still shown and unmount once hidden, and
 * everyone else springs to their new slot. The anchor (the person whose team
 * was just folded, say) keeps its spot on screen, so the pointer stays on it.
 * Cards and wires keep a stable DOM order, because moving an element in the
 * DOM cancels its running transition (and would lose a pointer capture mid-drag).
 */
export function useScene(layout: OrgLayout, anchorId: string | null, drag: DragState | null, highlighted: ReadonlySet<string>, animate: boolean) {
	const [scene, setScene] = React.useState<Scene>({ layout, before: null, leaving: EMPTY, shift: ORIGIN, beforeShift: ORIGIN });
	let current = scene;
	if (scene.layout !== layout) {
		current = nextScene(scene, layout, anchorId, animate);
		setScene(current);
	}
	const { before, leaving, shift, beforeShift } = current;

	// Once the last slide has settled, the cards that folded away can go.
	React.useEffect(() => {
		if (leaving.size === 0) return;
		const timer = window.setTimeout(() => setScene((latest) => (latest.leaving.size ? { ...latest, leaving: EMPTY } : latest)), CHART_SPRING.duration + 60);
		return () => window.clearTimeout(timer);
	}, [leaving]);

	const order = React.useRef<string[]>([]);

	return React.useMemo(() => {
		// Append-only order: survivors keep their place, newcomers join the end.
		const shown = new Set([...layout.byId.keys(), ...leaving.keys()]);
		const ids = order.current.filter((id) => shown.has(id));
		const placed = new Set(ids);
		for (const person of layout.people) if (!placed.has(person.data.id)) ids.push(person.data.id);
		order.current = ids;

		/** Where a card is heading: its slot, or its anchor's slot while it folds away. */
		const slotOf = (id: string): Spot | undefined => {
			const person = layout.byId.get(id);
			if (person) return { x: person.x + shift.x, y: person.y + shift.y, width: person.width, height: person.height };
			const item = leaving.get(id);
			const anchor = item ? layout.byId.get(item.anchorId) : undefined;
			return item && anchor ? { x: anchor.x + shift.x, y: anchor.y + shift.y, width: item.person.width, height: item.person.height } : undefined;
		};
		/** Where someone was drawn before this change. */
		const beforeOf = (id: string): Spot | undefined => {
			const person = before?.byId.get(id);
			return person && { x: person.x + beforeShift.x, y: person.y + beforeShift.y, width: person.width, height: person.height };
		};
		/** The slot plus the drag offset, while the card follows the pointer. */
		const spotOf = (id: string): Spot | undefined => {
			const slot = slotOf(id);
			return slot && drag?.id === id ? { ...slot, x: slot.x + drag.dx, y: slot.y + drag.dy } : slot;
		};
		/** Where a newly shown card grows from: the closest manager who was already on the chart, as they were. */
		const enterSpot = (person: PlacedPerson): Spot | undefined => {
			if (!before || before.byId.has(person.data.id)) return undefined;
			let source = person.parentId;
			while (source && !before.byId.has(source)) source = layout.byId.get(source)?.parentId ?? null;
			const from = source ? beforeOf(source) : undefined;
			return from ? { ...from, width: person.width, height: person.height } : undefined;
		};

		const cards: SceneCard[] = [];
		const wires: WireSpec[] = [];
		const anchors = new Map<string, AnchorSpec>();
		const addAnchor = (anchor: AnchorSpec) => {
			const existing = anchors.get(anchor.id);
			anchors.set(anchor.id, { ...anchor, live: anchor.live || Boolean(existing?.live), instant: anchor.instant || Boolean(existing?.instant) });
		};
		for (const id of ids) {
			const shown = layout.byId.get(id);
			const person = shown ?? leaving.get(id)!.person;
			const slot = slotOf(id)!;
			const enter = shown ? enterSpot(shown) : undefined;
			cards.push({ person, x: slot.x, y: slot.y, enterFrom: enter && { x: enter.x, y: enter.y }, leaving: !shown });

			const parentId = person.parentId;
			const parent = parentId ? spotOf(parentId) : undefined;
			// Over a new manager, the dragged card's own line gives way to the preview line.
			if (!parentId || !parent || (drag?.id === id && drag.targetId)) continue;
			const live = Boolean(shown) && highlighted.has(id);
			const instant = drag?.id === id || drag?.id === parentId;
			// A newly shown line grows from its manager's old spot, collapsed behind that card.
			const from = beforeOf(parentId) ?? (enter && shown?.parentId ? enterSpot(layout.byId.get(parentId)!) : undefined);
			const growFrom = from && bottom({ ...from, height: parent.height });
			const start = bottom(parent);
			const stack = person.stack;
			let line: Pick<WireSpec, 'start' | 'end' | 'via' | 'enter'>;
			if (stack && shown && !instant) {
				// A stacked report's line bends through its column; the layout drew it, so it only needs the scene's shift.
				const [first, ...bends] = stack.route.map(([x, y]): WirePoint => [x + shift.x, y + shift.y]);
				const end = bends.pop()!;
				line = { start: first, end, via: bends, enter: enter && growFrom ? { start: growFrom, end: growFrom, via: bends.map(() => growFrom) } : undefined };
			} else if (stack && !shown && !instant) {
				// Folding away: the same bends, all pulled into the manager's card, so the line retracts instead of jumping.
				line = { start, end: top(spotOf(id)!), via: stack.route.slice(2).map(() => start) };
			} else {
				line = { start, end: top(spotOf(id)!), enter: enter && growFrom ? { start: growFrom, end: top(enter) } : undefined };
			}
			wires.push({ id, ...line, tone: live ? 'live' : 'rest', marching: false, instant });
			addAnchor({ id: parentId, at: bottom(parent), live, instant, enter: growFrom });
		}
		const target = drag?.targetId ? spotOf(drag.targetId) : undefined;
		const dragged = drag ? spotOf(drag.id) : undefined;
		if (drag?.targetId && target && dragged) {
			wires.push({ id: `preview-${drag.id}`, start: bottom(target), end: top(dragged), tone: 'live', marching: animate, instant: true });
			addAnchor({ id: drag.targetId, at: bottom(target), live: true, instant: false });
		}
		// Anchors follow the card order too, so none of them moves in the DOM either.
		const orderedAnchors: AnchorSpec[] = [];
		for (const id of ids) {
			const anchor = anchors.get(id);
			if (anchor) orderedAnchors.push(anchor);
		}
		return { cards, wires, anchors: orderedAnchors, shift };
	}, [animate, before, beforeShift, drag, highlighted, layout, leaving, shift]);
}

import type * as React from 'react';

/**
 * A damped spring (mass 1) from 0 to 1, sampled into a CSS `linear()` easing.
 * CSS transitions keep hundreds of moving cards and wires inside the style
 * engine, which is far cheaper per frame than writing them from script, and
 * one shared curve keeps every wire attached to its cards.
 */
function springEasing(stiffness: number, damping: number, samples = 48) {
	const omega = Math.sqrt(stiffness);
	const zeta = damping / (2 * omega);
	const decay = zeta * omega;
	const damped = omega * Math.sqrt(Math.max(0, 1 - zeta * zeta));
	const at = (t: number) =>
		zeta < 1 ? 1 - Math.exp(-decay * t) * (Math.cos(damped * t) + (decay / damped) * Math.sin(damped * t)) : 1 - Math.exp(-omega * t) * (1 + omega * t);
	// Settled once the swing stays within 0.2% of the distance travelled.
	const envelope = zeta < 1 ? Math.sqrt(1 + (decay / damped) ** 2) : 1;
	const seconds = Math.log(envelope / 0.002) / decay;
	const points = Array.from({ length: samples + 1 }, (_, index) => (index === samples ? 1 : Math.round(at((index / samples) * seconds) * 1000) / 1000));
	return { easing: `linear(${points.join(', ')})`, duration: Math.round(seconds * 1000) };
}

/**
 * The chart's one spring: quick, with a whisper of overshoot (about 1.5%),
 * so a whole division unfolding feels physical without wobbling.
 */
export const CHART_SPRING = springEasing(420, 33);

/** Exposes the spring to every card, wire, and dot in the chart as CSS custom properties. */
export const CHART_SPRING_STYLE = {
	'--org-spring': CHART_SPRING.easing,
	'--org-spring-duration': `${CHART_SPRING.duration}ms`,
} as React.CSSProperties;

/** Tailwind classes for a spring transition on the given properties. */
export const springTransition = 'duration-(--org-spring-duration) ease-(--org-spring) motion-reduce:transition-none';

import { initials } from '@/lib/initials';

/** Up to 2 initials for a display name, or `null` when there are none so the avatar can show an icon instead. */
export function getInitials(name: string | null): string | null {
	return initials(name);
}

export function personName(person: { displayName: string | null }) {
	// A blank or whitespace-only name is as missing as a null one; an empty title would leave a card nobody can identify.
	return person.displayName?.trim() || 'Unnamed person';
}

export function reportsLabel(count: number) {
	return `${count} ${count === 1 ? 'report' : 'reports'}`;
}

/** A single edge in the org chart: one person and who they report to. */
export interface OrgChartEdge {
	/** Person ID. */
	id: string;
	/** ID of the person this edge reports to (null = root). */
	parentId: string | null;
	displayName: string | null;
	avatarUrl: string | null;
	positionTitle: string | null;
}

/** A person as the chart shows them, passed to node callbacks. */
export interface OrgChartNodeData extends OrgChartEdge {
	/** Direct reports, including any hidden while the node is collapsed. */
	childCount: number;
	isRoot: boolean;
	/** True while the chart is narrow enough to use compact cards. */
	isCompact: boolean;
}
